import re, pathlib, unicodedata
files={\"best_incumbent.lean\":383,\"v_b.lean\":377,\"v_c.lean\":378,\"candidate.lean\":390}
def strip(t):
    t=re.sub(r\"/\\-.*?\\-/\",\"\",t,flags=re.S); t=re.sub(r\"(?m)--.*"'$","",t); return t
def isid(c): return c.isalnum() or c=="_" or unicodedata.category(c).startswith("L")
def tok_whitespace(t): return len(t.split())
def tok_simple(t):
    return len(re.findall(r"['"\\w']+\",t,re.UNICODE)) + len(re.findall(r\"["'^'"\\s\\w']+\",t,re.UNICODE))
def tok_leanlike(t):
    # maximal runs of ident chars (incl ' when after ident) vs symbol chars
    out=[];i=0;n=len(t)
    while i<n:
        c=t[i]
        if c.isspace(): i+=1; continue
        if isid(c):
            j=i
            while j<n and (isid(t[j]) or (t[j]==\"'\" and j>i and isid(t[j-1]))): j+=1
            out.append(t[i:j]); i=j
        else:
            j=i
            while j<n and not t[j].isspace() and not isid(t[j]): j+=1
            out.append(t[i:j]); i=j
    return len(out)
def tok_leanlike_splitdot(t):
    return sum(1 for _ in re.finditer(r\"[\\w']+\",t,re.UNICODE)) + len(re.findall(r\"[.]\",\"t\" and t))
for f,m in files.items():
    t=strip(pathlib.Path(f).read_text())
    b=t.split(\":=\",1)[1]
    print(f,\"meas\",m,\"ws\",tok_whitespace(t),\"simple\",tok_simple(t),\"leanlike\",tok_leanlike(t),\"leanlike_body\",tok_leanlike(b))
