import re, pathlib, unicodedata
files={\"best_incumbent.lean\":383,\"v_b.lean\":377,\"v_c.lean\":378,\"candidate.lean\":390}
def strip(t):
    t=re.sub(r\"/\\-.*?\\-/\",\"\",t,flags=re.S); t=re.sub(r\"(?m)--.*"'$","",t); return t
def isid(c): return c.isalnum() or c=="_" or unicodedata.category(c).startswith("L")
def lex(t, dotmerge=True):
    out=[];i=0;n=len(t)
    while i<n:
        c=t[i]
        if c.isspace(): i+=1; continue
        if isid(c) or (dotmerge and c=='"'.'):
            j=i
            # atomic ident: (ident .)* ident
            while j<n:
                if isid(t[j]) or (t[j]==\"'\" and j>i): j+=1
                elif dotmerge and t[j]=='.' and j+1<n and (isid(t[j+1])): j+=1
                else: break
            out.append(t[i:j]); i=j
        else:
            j=i
            while j<n and not t[j].isspace() and not isid(t[j]) and t[j]"'!='"'.': j+=1
            out.append(t[i:j]); i=j
    return out
for f,m in files.items():
    t=strip(pathlib.Path(f).read_text())
    L=lex(t); B=lex(t.split(\":=\",1)[1])
    # also count only alpha-numeric idents
    print(f,\"meas\",m,\"dotmerge\",len(L),\"body\",len(B),\"idents\",sum(1 for x in L if isid(x[0])))
